<?php
require_once dirname(__DIR__).'/rent_reminder_lib.php';
try{$s=rr_settings();if($_SERVER['REQUEST_METHOD']!=='POST'||!$s||!hash_equals($s['gas_key'],(string)($_SERVER['HTTP_X_RENT_KEY']??'')))json_out(['ok'=>false],403);if(!$s['enabled'])json_out(['ok'=>true,'disabled'=>true]);rr_generate();$q=db()->prepare("SELECT q.id FROM lease_rent_send_queue q JOIN lease_rent_reminders r ON r.id=q.reminder_id WHERE q.status='pending' AND r.active=1 AND q.due_date BETWEEN r.start_date AND r.end_date AND q.due_date>=? AND q.scheduled_at<=? ORDER BY q.scheduled_at LIMIT 10");$q->execute([date('Y-m-d'),date('Y-m-d H:i:s')]);$out=[];foreach($q->fetchAll() as $v){try{$out[$v['id']]=rr_dispatch($v['id']);}catch(Throwable $e){$out[$v['id']]='skipped_or_error';}}json_out(['ok'=>true,'results'=>$out]);}catch(Throwable $e){json_out(['ok'=>false,'message'=>'서버 설정 또는 DB 오류'],500);}
